const KOEXP_RAW = JSON.parse("[{\"ko\":\"수고하세요\",\"c\":\"인사\",\"v\":\"상황따라\",\"sum\":\"딱 맞는 말은 없어요. 회사 동료끼리는 お疲れ様です, 가게를 나설 땐 그냥 ありがとうございました.\",\"ja\":[[\"お疲れ様です\",\"おつかれさまです\",\"동료·같이 일한 사람에게. 퇴근할 때도 OK\"],[\"ありがとうございました\",\"ありがとうございました\",\"가게·택시에서 내릴 때는 이게 자연스러워요\"]],\"no\":\"점원에게 お疲れ様です라고 하면 '같이 일하는 사람'처럼 들려서 어색해요.\",\"ex\":[\"お先に失礼します。お疲れ様です。\",\"おさきに しつれいします。 おつかれさまです。\",\"먼저 들어가 볼게요. 수고하세요.\"]},{\"ko\":\"수고하셨습니다\",\"c\":\"인사\",\"v\":\"있음\",\"sum\":\"お疲れ様でした가 딱 맞아요. 일이 끝난 뒤 윗사람에게도 그대로 쓸 수 있어요.\",\"ja\":[[\"お疲れ様でした\",\"おつかれさまでした\",\"일·행사를 마친 뒤 함께한 사람에게. 윗사람에게도 OK\"],[\"お疲れ様\",\"おつかれさま\",\"친구·후배에게 가볍게\"]],\"no\":\"ご苦労様でした는 윗사람이 아랫사람에게 하는 말이라, 상사에게 쓰면 실례가 될 수 있어요.\",\"ex\":[\"今日は一日お疲れ様でした。\",\"きょうは いちにち おつかれさまでした。\",\"오늘 하루 수고하셨습니다.\"]},{\"ko\":\"식사하셨어요?\",\"c\":\"인사\",\"v\":\"없음\",\"sum\":\"밥 먹었는지 묻는 걸 인사로 쓰는 문화가 없어요. 인사는 こんにちは나 날씨 이야기로 충분해요.\",\"ja\":[[\"こんにちは\",\"こんにちは\",\"그냥 인사가 목적이라면 이걸로\"],[\"いい天気ですね\",\"いいてんきですね\",\"가벼운 인사말로 날씨 얘기가 흔해요\"],[\"お昼もう食べました？\",\"おひるもうたべました？\",\"진짜로 같이 먹을지 물어볼 때만\"]],\"no\":\"인사로 ご飯食べましたか라고 하면 '같이 먹자는 건가?' 하고 진지하게 받아들일 수 있어요.\",\"ex\":[\"お昼もう食べた？まだなら一緒に行かない？\",\"おひる もう たべた？ まだなら いっしょに いかない？\",\"점심 먹었어? 아직이면 같이 갈래?\"]},{\"ko\":\"안녕히 가세요 / 안녕히 계세요\",\"c\":\"인사\",\"v\":\"상황따라\",\"sum\":\"가는 사람·남는 사람을 구분하는 인사가 없어요. 그리고 さようなら는 생각보다 잘 안 써요.\",\"ja\":[[\"お気をつけて\",\"おきをつけて\",\"떠나는 사람을 배웅할 때. '안녕히 가세요'와 가장 가까워요\"],[\"失礼します\",\"しつれいします\",\"회사·병원 등 공적인 자리를 나설 때\"],[\"じゃあ、またね\",\"じゃあ、またね\",\"친구끼리\"]],\"no\":\"さようなら는 '한동안 못 보는 작별' 느낌이 있어서, 어른끼리 매일 보는 사이에선 잘 안 써요.\",\"ex\":[\"今日はありがとうございました。お気をつけて。\",\"きょうは ありがとう ございました。 おきを つけて。\",\"오늘 감사했습니다. 안녕히 가세요.\"]},{\"ko\":\"다녀오겠습니다\",\"c\":\"인사\",\"v\":\"있음\",\"sum\":\"行ってきます가 딱 맞아요. 배웅하는 사람은 行ってらっしゃい로 받아요.\",\"ja\":[[\"行ってきます\",\"いってきます\",\"집을 나서는 사람이\"],[\"行ってらっしゃい\",\"いってらっしゃい\",\"배웅하는 사람이 '잘 다녀와'\"]],\"no\":\"\",\"ex\":[\"行ってきます。夕方には帰るね。\",\"いってきます。 ゆうがたには かえるね。\",\"다녀올게요. 저녁엔 돌아올게.\"]},{\"ko\":\"다녀왔습니다\",\"c\":\"인사\",\"v\":\"있음\",\"sum\":\"ただいま가 딱 맞아요. 맞이하는 쪽은 おかえり로 받아서 꼭 짝으로 주고받아요.\",\"ja\":[[\"ただいま\",\"ただいま\",\"집에 돌아온 사람이\"],[\"おかえり\",\"おかえり\",\"맞이하는 사람이 '잘 다녀왔어?'\"],[\"おかえりなさい\",\"おかえりなさい\",\"조금 더 정중하게\"]],\"no\":\"회사에선 외근 갔다 돌아와서 ただいま戻りました라고 해요. 가족끼리만 쓰는 말이 아니에요.\",\"ex\":[\"ただいま。今日は疲れたよ。\",\"ただいま。 きょうは つかれたよ。\",\"다녀왔습니다. 오늘은 피곤해.\"]},{\"ko\":\"잘 자\",\"c\":\"인사\",\"v\":\"있음\",\"sum\":\"おやすみ가 딱 맞아요. 정중하게는 おやすみなさい.\",\"ja\":[[\"おやすみ\",\"おやすみ\",\"친구·가족에게\"],[\"おやすみなさい\",\"おやすみなさい\",\"정중하게. 윗사람에게도 OK\"]],\"no\":\"자기 전만이 아니라 밤늦게 헤어질 때도 おやすみなさい라고 인사해요.\",\"ex\":[\"もう遅いから寝るね。おやすみ。\",\"もう おそいから ねるね。 おやすみ。\",\"이제 늦었으니까 잘게. 잘 자.\"]},{\"ko\":\"조심히 가\",\"c\":\"인사\",\"v\":\"있음\",\"sum\":\"気をつけてね가 딱 맞아요. 집에 가는 사람에겐 気をつけて帰ってね.\",\"ja\":[[\"気をつけてね\",\"きをつけてね\",\"친구·가족에게\"],[\"気をつけて帰ってね\",\"きをつけてかえってね\",\"집에 돌아가는 사람에게\"],[\"お気をつけてお帰りください\",\"おきをつけておかえりください\",\"손님에게 정중하게\"]],\"no\":\"\",\"ex\":[\"暗いから、気をつけて帰ってね。\",\"くらいから、 きを つけて かえってね。\",\"어두우니까 조심히 들어가.\"]},{\"ko\":\"다음에 봐\",\"c\":\"인사\",\"v\":\"있음\",\"sum\":\"またね가 딱 맞아요. 다음 만남이 정해져 있으면 また明日, また来週처럼 붙여요.\",\"ja\":[[\"またね\",\"またね\",\"친구에게 가장 흔한 작별 인사\"],[\"また今度\",\"またこんど\",\"날짜를 정하지 않은 '다음에'\"],[\"また来週\",\"またらいしゅう\",\"다음 주에 만날 게 정해져 있을 때\"]],\"no\":\"\",\"ex\":[\"じゃあ、また来週ね。\",\"じゃあ、 また らいしゅうね。\",\"그럼 다음 주에 봐.\"]},{\"ko\":\"새해 복 많이 받으세요\",\"c\":\"인사\",\"v\":\"상황따라\",\"sum\":\"언제 말하느냐가 핵심이에요. 12월엔 良いお年を, 1월 1일부터는 あけましておめでとうございます.\",\"ja\":[[\"良いお年を\",\"よいおとしを\",\"연말에 헤어질 때 '좋은 새해 맞으세요'\"],[\"あけましておめでとうございます\",\"あけましておめでとうございます\",\"해가 바뀐 뒤에\"],[\"今年もよろしくお願いします\",\"ことしもよろしくおねがいします\",\"새해 인사 뒤에 거의 꼭 붙여요\"]],\"no\":\"あけましておめでとう를 12월에 미리 말하면 틀려요. 일본은 양력 새해만 쇠기 때문에 설날(음력) 인사도 통하지 않아요.\",\"ex\":[\"あけましておめでとうございます。今年もよろしくお願いします。\",\"あけまして おめでとう ございます。 ことしも よろしく おねがいします。\",\"새해 복 많이 받으세요. 올해도 잘 부탁드려요.\"]},{\"ko\":\"생일 축하해\",\"c\":\"인사\",\"v\":\"있음\",\"sum\":\"誕生日おめでとう가 딱 맞아요. 정중하게는 お誕生日おめでとうございます.\",\"ja\":[[\"誕生日おめでとう\",\"たんじょうびおめでとう\",\"친구·가족에게\"],[\"お誕生日おめでとうございます\",\"おたんじょうびおめでとうございます\",\"윗사람에게 정중하게\"]],\"no\":\"\",\"ex\":[\"誕生日おめでとう！素敵な一年になりますように。\",\"たんじょうび おめでとう！ すてきな いちねんに なりますように。\",\"생일 축하해! 멋진 한 해가 되길.\"]},{\"ko\":\"들어가세요\",\"c\":\"인사\",\"v\":\"없음\",\"sum\":\"전화를 끊거나 헤어질 때 하는 '들어가세요' 같은 인사는 없어요. 상황에 맞는 다른 인사를 써요.\",\"ja\":[[\"失礼します\",\"しつれいします\",\"전화를 끊을 때\"],[\"お気をつけて\",\"おきをつけて\",\"헤어지는 사람을 배웅할 때\"]],\"no\":\"入ってください라고 직역하면 '안으로 들어오세요'라는 뜻이라 상대가 당황해요.\",\"ex\":[\"では、失礼します。\",\"では、 しつれいします。\",\"그럼 들어가세요. (전화 끊을 때)\"]},{\"ko\":\"잘 먹겠습니다\",\"c\":\"식사\",\"v\":\"있음\",\"sum\":\"いただきます가 딱 맞아요. 손을 모으고 말하는 사람이 많아요.\",\"ja\":[[\"いただきます\",\"いただきます\",\"먹기 직전에. 누가 사 주지 않아도 써요\"]],\"no\":\"한국에선 대접받을 때 주로 하지만, 일본에선 혼자 먹을 때도 いただきます라고 해요.\",\"ex\":[\"わあ、おいしそう。いただきます。\",\"わあ、 おいしそう。 いただきます。\",\"와, 맛있겠다. 잘 먹겠습니다.\"]},{\"ko\":\"잘 먹었습니다\",\"c\":\"식사\",\"v\":\"있음\",\"sum\":\"ごちそうさまでした가 딱 맞아요. 식당을 나설 때 직원에게 해도 자연스러워요.\",\"ja\":[[\"ごちそうさまでした\",\"ごちそうさまでした\",\"다 먹은 뒤, 사 준 사람이나 가게 직원에게\"],[\"ごちそうさま\",\"ごちそうさま\",\"가족·친구끼리 가볍게\"]],\"no\":\"\",\"ex\":[\"ごちそうさまでした。とてもおいしかったです。\",\"ごちそうさまでした。 とても おいしかったです。\",\"잘 먹었습니다. 정말 맛있었어요.\"]},{\"ko\":\"맛있게 드세요\",\"c\":\"식사\",\"v\":\"없음\",\"sum\":\"'맛있게'를 붙여 권하는 인사는 없어요. 가게에선 ごゆっくりどうぞ, 집에선 どうぞ 정도로 말해요.\",\"ja\":[[\"ごゆっくりどうぞ\",\"ごゆっくりどうぞ\",\"가게 직원이 음식을 내며. '천천히 즐기세요'라는 뜻\"],[\"どうぞ召し上がってください\",\"どうぞめしあがってください\",\"손님에게 음식을 정중하게 권할 때\"],[\"召し上がれ\",\"めしあがれ\",\"음식을 차려 준 사람이 다정하게. いただきます에 대한 대답으로도 써요\"]],\"no\":\"おいしく食べてください는 직역이라 어색해요.\",\"ex\":[\"お待たせしました。ごゆっくりどうぞ。\",\"おまたせしました。 ごゆっくり どうぞ。\",\"오래 기다리셨습니다. 맛있게 드세요.\"]},{\"ko\":\"많이 드세요\",\"c\":\"식사\",\"v\":\"상황따라\",\"sum\":\"집에서 대접할 땐 たくさん食べてね라고 해요. 손님에겐 '사양 말고'라는 뜻의 遠慮なく가 자연스러워요.\",\"ja\":[[\"たくさん食べてね\",\"たくさんたべてね\",\"가족·친구·아이에게\"],[\"遠慮なくどうぞ\",\"えんりょなくどうぞ\",\"손님에게 '사양 말고 드세요'\"],[\"どんどん食べてください\",\"どんどんたべてください\",\"음식이 넉넉할 때 계속 권하며\"]],\"no\":\"식당 직원이 손님에게 하는 인사로는 안 써요. 집이나 모임에서 대접하는 쪽이 하는 말이에요.\",\"ex\":[\"いっぱい作ったから、遠慮しないで食べてね。\",\"いっぱい つくったから、 えんりょ しないで たべてね。\",\"많이 만들었으니까 사양 말고 많이 먹어.\"]},{\"ko\":\"시원하다 (국물)\",\"c\":\"식사\",\"v\":\"없음\",\"sum\":\"뜨거운 국물이 '시원하다'는 표현은 일본 사람에게 수수께끼예요. 대신 '몸에 스며든다(染みる)'고 해요.\",\"ja\":[[\"染みる\",\"しみる\",\"뜨거운 국물이 몸에 쫙 퍼질 때\"],[\"ほっとする味\",\"ほっとするあじ\",\"속이 편안해지는 따뜻한 맛\"],[\"だしが効いてる\",\"だしがきいてる\",\"국물 맛이 깊고 개운할 때\"]],\"no\":\"涼しい는 날씨·바람 같은 '선선함'에 쓰는 말이에요. 국물에 쓰면 전혀 뜻이 통하지 않아요.\",\"ex\":[\"このスープ、体に染みるね。\",\"この スープ、 からだに しみるね。\",\"이 국물 진짜 시원하다.\"]},{\"ko\":\"출출하다\",\"c\":\"식사\",\"v\":\"있음\",\"sum\":\"小腹がすいた가 딱 맞아요. '배가 조금 고프다'는 뜻이에요.\",\"ja\":[[\"小腹がすいた\",\"こばらがすいた\",\"식사 사이에 살짝 배고플 때\"],[\"ちょっとお腹すいた\",\"ちょっとおなかすいた\",\"더 일상적으로\"]],\"no\":\"\",\"ex\":[\"小腹がすいたから、コンビニ行かない？\",\"こばらが すいたから、 コンビニ いかない？\",\"출출한데 편의점 갈래?\"]},{\"ko\":\"느끼하다\",\"c\":\"식사\",\"v\":\"상황따라\",\"sum\":\"기름진 음식은 脂っこい, 진해서 질리는 맛은 くどい예요. 사람이 느끼할 땐 キザ.\",\"ja\":[[\"脂っこい\",\"あぶらっこい\",\"기름진 음식이 느끼할 때\"],[\"くどい\",\"くどい\",\"맛이 너무 진하고 무거워서 질릴 때\"],[\"キザ\",\"キザ\",\"사람의 말·행동이 느끼할 때\"]],\"no\":\"느끼한 남자를 脂っこい라고 하면 '피부가 번들거린다'처럼 들릴 수 있어요. 이럴 땐 キザ.\",\"ex\":[\"天ぷらばかりで、ちょっと脂っこいね。\",\"てんぷら ばかりで、 ちょっと あぶらっこいね。\",\"튀김만 있어서 좀 느끼하다.\"]},{\"ko\":\"한잔하자\",\"c\":\"식사\",\"v\":\"있음\",\"sum\":\"一杯どう？가 딱 맞아요. '가볍게 한잔'이라는 느낌까지 비슷해요.\",\"ja\":[[\"一杯どう？\",\"いっぱいどう？\",\"친구·동료에게 가볍게\"],[\"飲みに行こうよ\",\"のみにいこうよ\",\"'술 마시러 가자'\"],[\"軽く一杯行きませんか\",\"かるくいっぱいいきませんか\",\"윗사람에게 정중하게\"]],\"no\":\"\",\"ex\":[\"仕事終わったら、一杯どう？\",\"しごと おわったら、 いっぱい どう？\",\"일 끝나고 한잔할래?\"]},{\"ko\":\"건배\",\"c\":\"식사\",\"v\":\"있음\",\"sum\":\"乾杯(かんぱい)로 똑같이 써요. 회식에선 お疲れ様でした와 함께 외치는 경우가 많아요.\",\"ja\":[[\"乾杯\",\"かんぱい\",\"다 같이 잔을 들며\"],[\"お疲れ様でした、乾杯\",\"おつかれさまでした、かんぱい\",\"회식의 첫 건배로 흔한 말\"]],\"no\":\"'원샷'은 一気(いっき)라고 하는데, 억지로 시키면 アルハラ(음주 강요)로 여겨져요.\",\"ex\":[\"それでは、皆さんお疲れ様でした。乾杯！\",\"それでは、 みなさん おつかれさまでした。 かんぱい！\",\"자, 모두 수고하셨습니다. 건배!\"]},{\"ko\":\"화이팅\",\"c\":\"응원·위로\",\"v\":\"상황따라\",\"sum\":\"頑張って가 가장 가까워요. ファイト도 쓰지만 주로 운동부 응원 구호 느낌이에요.\",\"ja\":[[\"頑張って\",\"がんばって\",\"친구·가족에게 가장 무난한 응원\"],[\"頑張ってください\",\"がんばってください\",\"윗사람에게 정중하게\"],[\"ファイト\",\"ファイト\",\"운동부·응원 구호 느낌. 일상 대화에선 덜 써요\"]],\"no\":\"'ファイティン'은 K-POP을 아는 사람에게만 통해요. 일반적으로는 頑張って가 확실해요.\",\"ex\":[\"明日の試験、頑張ってね。\",\"あしたの しけん、 がんばってね。\",\"내일 시험 화이팅!\"]},{\"ko\":\"힘내\",\"c\":\"응원·위로\",\"v\":\"상황따라\",\"sum\":\"기운 없는 사람에겐 元気出して, 도전하는 사람에겐 頑張って예요.\",\"ja\":[[\"元気出して\",\"げんきだして\",\"기운 없고 우울한 사람에게\"],[\"頑張って\",\"がんばって\",\"뭔가에 도전하는 사람에게\"],[\"無理しないでね\",\"むりしないでね\",\"이미 열심히 하는 사람에겐 이게 더 위로가 돼요\"]],\"no\":\"많이 지친 사람에게 頑張って라고 하면 '더 열심히 하라고?'처럼 부담이 될 수 있어요.\",\"ex\":[\"落ち込まないで。元気出して。\",\"おちこまないで。 げんき だして。\",\"기죽지 마. 힘내.\"]},{\"ko\":\"고생 많았어\",\"c\":\"응원·위로\",\"v\":\"상황따라\",\"sum\":\"일을 마친 사람에겐 お疲れ様, 힘든 일을 겪은 사람에겐 大変だったね가 자연스러워요.\",\"ja\":[[\"お疲れ様\",\"おつかれさま\",\"일이나 행사를 마친 친구에게\"],[\"大変だったね\",\"たいへんだったね\",\"힘든 일을 겪은 사람에게 공감하며\"],[\"よく頑張ったね\",\"よくがんばったね\",\"노력한 과정을 칭찬하며\"]],\"no\":\"お疲れ様는 '일'에 대한 인사라서, 아팠거나 속상한 일을 겪은 친구에겐 大変だったね가 더 따뜻해요.\",\"ex\":[\"引っ越し、大変だったね。本当にお疲れ様。\",\"ひっこし、 たいへん だったね。 ほんとうに おつかれさま。\",\"이사하느라 고생 많았어. 정말 수고했어.\"]},{\"ko\":\"몸조리 잘하세요\",\"c\":\"응원·위로\",\"v\":\"있음\",\"sum\":\"お大事に가 딱 맞아요. 병원에서 나갈 때 직원이 하는 말도 이거예요.\",\"ja\":[[\"お大事に\",\"おだいじに\",\"아픈 사람에게\"],[\"お大事にしてください\",\"おだいじにしてください\",\"윗사람에게 정중하게\"],[\"無理しないでね\",\"むりしないでね\",\"친구에게 '무리하지 마'\"]],\"no\":\"건강한 사람에게 헤어지며 お大事に라고 하면 '어디 아파?' 하고 의아해해요.\",\"ex\":[\"熱があるなら、今日はゆっくり休んで。お大事に。\",\"ねつが あるなら、 きょうは ゆっくり やすんで。 おだいじに。\",\"열 있으면 오늘은 푹 쉬어. 몸조리 잘해.\"]},{\"ko\":\"축하해\",\"c\":\"응원·위로\",\"v\":\"있음\",\"sum\":\"おめでとう가 딱 맞아요. 윗사람에겐 おめでとうございます.\",\"ja\":[[\"おめでとう\",\"おめでとう\",\"친구·가족에게\"],[\"おめでとうございます\",\"おめでとうございます\",\"윗사람에게 정중하게\"]],\"no\":\"'축하합니다'를 お祝いします로 직역하면 어색해요. おめでとうございます면 충분해요.\",\"ex\":[\"合格おめでとう！本当によかったね。\",\"ごうかく おめでとう！ ほんとうに よかったね。\",\"합격 축하해! 정말 잘됐다.\"]},{\"ko\":\"잘했어\",\"c\":\"응원·위로\",\"v\":\"상황따라\",\"sum\":\"친구나 아이가 뭔가 해냈을 땐 えらい, '역시 대단해'는 さすが예요.\",\"ja\":[[\"えらいね\",\"えらいね\",\"아이·친구에게 '잘했어, 기특해'\"],[\"さすが\",\"さすが\",\"'역시 대단해' (윗사람에겐 さすがです)\"],[\"よくできました\",\"よくできました\",\"선생님이 학생에게 (칭찬 도장에 찍힌 그 말)\"]],\"no\":\"えらい를 윗사람에게 쓰면 '기특하네'처럼 위에서 내려다보는 말이 돼요.\",\"ex\":[\"毎日自炊してるの？えらいね。\",\"まいにち じすい してるの？ えらいね。\",\"매일 밥 해 먹어? 잘한다!\"]},{\"ko\":\"괜찮아, 괜찮아 (위로)\",\"c\":\"응원·위로\",\"v\":\"있음\",\"sum\":\"실수한 사람에겐 ドンマイ가 딱이에요. '신경 쓰지 마'는 気にしないで.\",\"ja\":[[\"ドンマイ\",\"ドンマイ\",\"실수한 친구·팀원에게. 스포츠에서 특히 많이 써요\"],[\"気にしないで\",\"きにしないで\",\"'신경 쓰지 마'\"],[\"大丈夫だよ\",\"だいじょうぶだよ\",\"다정하게 안심시킬 때\"]],\"no\":\"\",\"ex\":[\"ドンマイ！次があるよ。\",\"ドンマイ！ つぎが あるよ。\",\"괜찮아 괜찮아! 다음이 있잖아.\"]},{\"ko\":\"잠깐만요\",\"c\":\"일상\",\"v\":\"상황따라\",\"sum\":\"'기다려 달라'는 ちょっと待ってください, 붐비는 곳에서 지나갈 땐 すみません이에요.\",\"ja\":[[\"ちょっと待ってください\",\"ちょっとまってください\",\"'잠깐 기다려 주세요'의 뜻일 때\"],[\"すみません、降ります\",\"すみません、おります\",\"붐비는 전철에서 내릴 때\"],[\"少々お待ちください\",\"しょうしょうおまちください\",\"가게·전화에서 정중하게\"]],\"no\":\"지나가려고 ちょっと待って라고 하면 '거기 서!'처럼 들려요. 길을 비켜 달라는 '잠깐만요'는 すみません.\",\"ex\":[\"すみません、降ります。\",\"すみません、 おります。\",\"잠깐만요, 내릴게요.\"]},{\"ko\":\"빨리빨리\",\"c\":\"일상\",\"v\":\"상황따라\",\"sum\":\"아이나 친구를 재촉할 땐 早く早く, '서둘러'는 急いで예요. 다만 일본에선 남을 재촉하는 말을 잘 안 해요.\",\"ja\":[[\"早く早く\",\"はやくはやく\",\"아이·친구를 재촉할 때\"],[\"急いで\",\"いそいで\",\"'서둘러'\"],[\"急いでいるんですが\",\"いそいでいるんですが\",\"가게에서 사정을 말하며 부탁할 때\"]],\"no\":\"가게에서 '빨리 주세요'라고 재촉하면 실례가 될 수 있어요. 急いでいるんですが처럼 사정을 말하는 게 좋아요.\",\"ex\":[\"急いで！電車が来ちゃう。\",\"いそいで！ でんしゃが きちゃう。\",\"빨리빨리! 전철 온다.\"]},{\"ko\":\"연락할게\",\"c\":\"일상\",\"v\":\"있음\",\"sum\":\"また連絡するね가 딱 맞아요. 일본에선 연락의 대부분이 LINE이라 LINEするね라고도 해요.\",\"ja\":[[\"また連絡するね\",\"またれんらくするね\",\"친구에게\"],[\"後で連絡します\",\"あとでれんらくします\",\"정중하게 '나중에 연락드릴게요'\"],[\"LINEするね\",\"ラインするね\",\"한국의 '카톡할게'와 같은 느낌\"]],\"no\":\"\",\"ex\":[\"着いたらLINEするね。\",\"ついたら ライン するね。\",\"도착하면 연락할게.\"]},{\"ko\":\"애매하다\",\"c\":\"일상\",\"v\":\"상황따라\",\"sum\":\"말·태도가 애매하면 曖昧(한자도 같아요), 좋은지 나쁜지 애매하면 微妙예요.\",\"ja\":[[\"微妙\",\"びみょう\",\"'좀 별로인데…'라는 뜻의 애매함\"],[\"曖昧\",\"あいまい\",\"말·태도가 분명하지 않을 때\"]],\"no\":\"'이 옷 애매해'를 曖昧だ라고 하면 어색해요. 이럴 땐 微妙.\",\"ex\":[\"この服、ちょっと微妙かも。\",\"この ふく、 ちょっと びみょうかも。\",\"이 옷 좀 애매한 것 같아.\"]},{\"ko\":\"아깝다\",\"c\":\"일상\",\"v\":\"상황따라\",\"sum\":\"버리기 아까운 건 もったいない, 아슬아슬하게 놓친 건 惜しい예요.\",\"ja\":[[\"もったいない\",\"もったいない\",\"버리거나 낭비하기 아까울 때\"],[\"惜しい\",\"おしい\",\"조금 차이로 놓쳤을 때 '아깝다!'\"]],\"no\":\"\",\"ex\":[\"まだ食べられるのに、捨てるのはもったいないよ。\",\"まだ たべられるのに、 すてるのは もったいないよ。\",\"아직 먹을 수 있는데 버리긴 아까워.\"]},{\"ko\":\"실례합니다\",\"c\":\"일상\",\"v\":\"있음\",\"sum\":\"失礼します가 딱 맞아요. 방에 들어갈 때, 나갈 때, 전화 끊을 때까지 두루 써요.\",\"ja\":[[\"失礼します\",\"しつれいします\",\"방에 들어가거나 나갈 때, 전화를 끊을 때\"],[\"失礼しました\",\"しつれいしました\",\"면접·교무실 등에서 방을 나올 때\"],[\"お先に失礼します\",\"おさきにしつれいします\",\"먼저 퇴근할 때\"]],\"no\":\"\",\"ex\":[\"失礼します。山田先生はいらっしゃいますか。\",\"しつれいします。 やまだ せんせいは いらっしゃいますか。\",\"실례합니다. 야마다 선생님 계세요?\"]},{\"ko\":\"아 그래요? (맞장구)\",\"c\":\"일상\",\"v\":\"있음\",\"sum\":\"そうなんですね가 딱 맞아요. 일본 사람은 맞장구를 아주 자주 쳐서, 섞어 쓰면 대화가 훨씬 자연스러워져요.\",\"ja\":[[\"そうなんですね\",\"そうなんですね\",\"정중하게 '아, 그렇군요'\"],[\"へえ\",\"へえ\",\"놀라거나 감탄하며 '오~'\"],[\"なるほど\",\"なるほど\",\"납득할 때. 윗사람에게 너무 자주 쓰면 건방져 보일 수 있어요\"]],\"no\":\"맞장구 없이 조용히 듣기만 하면 '내 얘기 듣고 있나?' 하고 불안해할 수 있어요.\",\"ex\":[\"へえ、そうなんですね。知らなかったです。\",\"へえ、 そうなんですね。 しらなかったです。\",\"아, 그래요? 몰랐어요.\"]},{\"ko\":\"답답하다\",\"c\":\"감정\",\"v\":\"상황따라\",\"sum\":\"한 단어로는 안 돼요. 뜻대로 안 될 땐 もどかしい, 속이 꽉 막힌 기분은 モヤモヤする.\",\"ja\":[[\"もどかしい\",\"もどかしい\",\"뜻대로 안 돼서 답답할 때\"],[\"モヤモヤする\",\"モヤモヤする\",\"마음이 개운치 않고 답답할 때\"],[\"息苦しい\",\"いきぐるしい\",\"공간이 좁고 공기가 갑갑할 때\"]],\"no\":\"\",\"ex\":[\"言いたいことがうまく言えなくて、もどかしい。\",\"いいたい ことが うまく いえなくて、 もどかしい。\",\"하고 싶은 말을 잘 못 해서 답답해.\"]},{\"ko\":\"서운하다\",\"c\":\"감정\",\"v\":\"상황따라\",\"sum\":\"헤어지는 서운함은 寂しい, '나한테 말도 안 하고!' 하는 서운함은 水くさい예요.\",\"ja\":[[\"寂しい\",\"さびしい\",\"헤어지거나 떠날 때의 서운함\"],[\"水くさい\",\"みずくさい\",\"'우리 사이에 왜 말 안 했어?' 하는 서운함\"],[\"ちょっと悲しい\",\"ちょっとかなしい\",\"상대의 말·행동에 마음이 상했을 때 부드럽게\"]],\"no\":\"\",\"ex\":[\"引っ越すなんて聞いてないよ。水くさいなあ。\",\"ひっこす なんて きいて ないよ。 みずくさいなあ。\",\"이사 간다는 얘기 못 들었어. 서운하다.\"]},{\"ko\":\"억울하다\",\"c\":\"감정\",\"v\":\"상황따라\",\"sum\":\"딱 맞는 단어는 없어요. 누명이면 濡れ衣, 부당하면 納得いかない, 져서 분하면 悔しい.\",\"ja\":[[\"納得いかない\",\"なっとくいかない\",\"결과나 대우를 받아들일 수 없을 때\"],[\"濡れ衣だ\",\"ぬれぎぬだ\",\"하지도 않은 일로 누명을 썼을 때\"],[\"悔しい\",\"くやしい\",\"노력했는데 져서 분할 때 ('분하다'에 가까워요)\"]],\"no\":\"悔しい는 '분하다'는 느낌이 강해서, 누명을 쓴 억울함에는 잘 안 맞아요.\",\"ex\":[\"私じゃないのに怒られて、納得いかない。\",\"わたしじゃ ないのに おこられて、 なっとく いかない。\",\"내가 한 것도 아닌데 혼나서 억울해.\"]},{\"ko\":\"아이고\",\"c\":\"감정\",\"v\":\"상황따라\",\"sum\":\"'아이고'가 하는 일을 상황마다 다른 말이 나눠 맡아요. 일어날 땐 よいしょ, 남의 실수엔 あらら.\",\"ja\":[[\"よいしょ\",\"よいしょ\",\"앉거나 일어날 때, 무거운 걸 들 때\"],[\"あらら\",\"あらら\",\"누가 넘어지거나 실수했을 때\"],[\"やれやれ\",\"やれやれ\",\"지쳐서 한숨 쉬듯 '아이고 참'\"]],\"no\":\"\",\"ex\":[\"よいしょ。最近、立つだけで疲れるなあ。\",\"よいしょ。 さいきん、 たつだけで つかれるなあ。\",\"아이고. 요즘은 일어나기만 해도 피곤하네.\"]},{\"ko\":\"대박\",\"c\":\"감정\",\"v\":\"상황따라\",\"sum\":\"누구에게나 쓸 수 있는 건 すごい, 친구끼리는 やばい가 가장 가까워요.\",\"ja\":[[\"すごい\",\"すごい\",\"누구에게나 쓸 수 있는 무난한 '대박'\"],[\"やばい\",\"やばい\",\"젊은 층 구어. 좋을 때도 나쁠 때도 써요\"],[\"最高\",\"さいこう\",\"정말 좋을 때 '대박 좋아'\"]],\"no\":\"やばい는 친구끼리만 써요. 윗사람 앞이나 정중한 자리에선 すごいですね가 안전해요.\",\"ex\":[\"このラーメン、やばい。めっちゃおいしい。\",\"この ラーメン、 やばい。 めっちゃ おいしい。\",\"이 라멘 대박. 완전 맛있어.\"]},{\"ko\":\"헐\",\"c\":\"감정\",\"v\":\"상황따라\",\"sum\":\"놀랐을 땐 えっ, '헐 진짜?'는 うそ나 マジで예요.\",\"ja\":[[\"えっ\",\"えっ\",\"놀랐을 때 가장 기본\"],[\"うそ\",\"うそ\",\"'헐, 진짜?' (비난이 아니라 감탄)\"],[\"マジで\",\"マジで\",\"친구끼리 '헐 진심?'\"]],\"no\":\"うそ!는 감탄사라서 '거짓말하지 마'라는 비난은 아니에요. 그래도 윗사람에겐 本当ですか가 좋아요.\",\"ex\":[\"えっ、うそ。もう売り切れ？\",\"えっ、 うそ。 もう うりきれ？\",\"헐. 벌써 품절이야?\"]},{\"ko\":\"짜증나\",\"c\":\"감정\",\"v\":\"있음\",\"sum\":\"イライラする가 가장 가까워요. 화가 날 정도면 ムカつく.\",\"ja\":[[\"イライラする\",\"イライラする\",\"짜증이 쌓여 신경이 곤두설 때\"],[\"ムカつく\",\"ムカつく\",\"화가 날 만큼 짜증날 때. 친구끼리만\"],[\"もう、嫌だ\",\"もう、いやだ\",\"상황이 짜증날 때 혼잣말로\"]],\"no\":\"うざい는 사람에게 직접 쓰면 꽤 상처 주는 말이라 피하는 게 좋아요.\",\"ex\":[\"電車がまた遅れてる。イライラするなあ。\",\"でんしゃが また おくれてる。 イライラ するなあ。\",\"전철이 또 늦네. 짜증나.\"]},{\"ko\":\"귀찮아\",\"c\":\"감정\",\"v\":\"있음\",\"sum\":\"めんどくさい가 딱 맞아요. 친구끼리는 줄여서 めんどい라고도 해요.\",\"ja\":[[\"めんどくさい\",\"めんどくさい\",\"일상 구어 '귀찮아'\"],[\"面倒くさい\",\"めんどうくさい\",\"원래 형태. 글로 쓸 때\"],[\"めんどい\",\"めんどい\",\"친구끼리 아주 가볍게\"]],\"no\":\"사람을 두고 めんどくさい人라고 하면 '피곤한 사람'이라는 꽤 센 말이 돼요.\",\"ex\":[\"今日は料理するのがめんどくさい。\",\"きょうは りょうり するのが めんどくさい。\",\"오늘은 요리하기 귀찮아.\"]},{\"ko\":\"어떡해\",\"c\":\"감정\",\"v\":\"상황따라\",\"sum\":\"내가 곤란할 땐 どうしよう, 친구의 안 좋은 소식에 공감할 땐 大変だね예요.\",\"ja\":[[\"どうしよう\",\"どうしよう\",\"내가 곤란할 때 '어떡하지'\"],[\"大変だね\",\"たいへんだね\",\"친구의 안 좋은 소식을 듣고 '어떡해…'\"],[\"かわいそうに\",\"かわいそうに\",\"안타까운 일에. 당사자에게 직접 쓰는 건 조심\"]],\"no\":\"친구 고민을 듣고 どうしよう라고 하면 '내가 어떡하지?'처럼 들려요. 공감할 땐 大変だね.\",\"ex\":[\"財布を忘れた。どうしよう。\",\"さいふを わすれた。 どうしよう。\",\"지갑 놓고 왔어. 어떡해.\"]},{\"ko\":\"속이 시원하다\",\"c\":\"감정\",\"v\":\"있음\",\"sum\":\"スッキリした가 딱 맞아요. 통쾌한 느낌이면 スカッとする.\",\"ja\":[[\"スッキリした\",\"スッキリした\",\"고민·할 말을 털어놓고 후련할 때\"],[\"スカッとする\",\"スカッとする\",\"통쾌해서 속이 뻥 뚫릴 때\"]],\"no\":\"\",\"ex\":[\"言いたいこと全部言って、スッキリした。\",\"いいたい こと ぜんぶ いって、 スッキリ した。\",\"하고 싶은 말 다 했더니 속이 시원하다.\"]},{\"ko\":\"아쉽다\",\"c\":\"감정\",\"v\":\"상황따라\",\"sum\":\"결과가 아쉬우면 残念, 헤어지기 아쉬우면 名残惜しい예요.\",\"ja\":[[\"残念\",\"ざんねん\",\"기대와 달라서 아쉬울 때\"],[\"名残惜しい\",\"なごりおしい\",\"헤어지기 아쉬울 때\"],[\"物足りない\",\"ものたりない\",\"뭔가 조금 부족해서 아쉬울 때\"]],\"no\":\"\",\"ex\":[\"もう帰るの？名残惜しいなあ。\",\"もう かえるの？ なごりおしいなあ。\",\"벌써 가? 아쉽다.\"]},{\"ko\":\"시원섭섭하다\",\"c\":\"감정\",\"v\":\"없음\",\"sum\":\"한 단어로는 없어요. '후련한 것 같기도, 서운한 것 같기도'처럼 두 감정을 나란히 말해요.\",\"ja\":[[\"ほっとしたような、寂しいような\",\"ほっとしたような、さびしいような\",\"두 감정을 나란히 말해서 표현\"]],\"no\":\"\",\"ex\":[\"卒業できて、ほっとしたような、寂しいような気持ち。\",\"そつぎょう できて、 ほっと したような、 さびしいような きもち。\",\"졸업해서 시원섭섭한 기분이야.\"]},{\"ko\":\"잘 부탁드립니다\",\"c\":\"관계\",\"v\":\"있음\",\"sum\":\"よろしくお願いします가 딱 맞아요. 일본에선 훨씬 더 자주, 메일 끝마다 붙일 정도로 써요.\",\"ja\":[[\"よろしくお願いします\",\"よろしくおねがいします\",\"처음 만날 때, 부탁할 때, 메일 끝맺음\"],[\"よろしくお願いいたします\",\"よろしくおねがいいたします\",\"더 정중하게. 비즈니스 메일에서\"],[\"よろしくね\",\"よろしくね\",\"친구끼리 가볍게\"]],\"no\":\"\",\"ex\":[\"はじめまして、キムです。よろしくお願いします。\",\"はじめまして、 キムです。 よろしく おねがいします。\",\"처음 뵙겠습니다, 김이에요. 잘 부탁드립니다.\"]},{\"ko\":\"밥 한번 먹자\",\"c\":\"관계\",\"v\":\"있음\",\"sum\":\"今度ご飯行こう가 거의 같아요. 일본에서도 인사치레로 끝나는 경우가 많은 것까지 비슷해요.\",\"ja\":[[\"今度ご飯行こうよ\",\"こんどごはんいこうよ\",\"친구에게\"],[\"今度お食事でもいかがですか\",\"こんどおしょくじでもいかがですか\",\"윗사람·거래처에 정중하게\"]],\"no\":\"'한번'을 一回로 직역하면 어색해요. 今度(다음에)를 써요.\",\"ex\":[\"久しぶり！今度ご飯行こうよ。\",\"ひさしぶり！ こんど ごはん いこうよ。\",\"오랜만이다! 언제 밥 한번 먹자.\"]},{\"ko\":\"눈치\",\"c\":\"관계\",\"v\":\"상황따라\",\"sum\":\"'눈치' 한 단어는 없지만 상황마다 표현이 있어요. 분위기 파악은 空気を読む, 눈치가 빠른 건 察しがいい.\",\"ja\":[[\"空気を読む\",\"くうきをよむ\",\"분위기를 파악하다 (눈치가 있다)\"],[\"顔色をうかがう\",\"かおいろをうかがう\",\"남의 눈치를 보다\"],[\"察しがいい\",\"さっしがいい\",\"말 안 해도 알아채다 (눈치가 빠르다)\"]],\"no\":\"\",\"ex\":[\"彼は本当に空気が読める人だね。\",\"かれは ほんとうに くうきが よめる ひとだね。\",\"그 사람 진짜 눈치 있다.\"]},{\"ko\":\"정\",\"c\":\"관계\",\"v\":\"상황따라\",\"sum\":\"情라는 한자는 있지만 한국의 '정'만큼 넓게 쓰진 않아요. '정들다'는 情が移る, '정이 많다'는 情に厚い.\",\"ja\":[[\"情が移る\",\"じょうがうつる\",\"함께 지내다 보니 정이 들다\"],[\"愛着がわく\",\"あいちゃくがわく\",\"물건·장소에 정이 들다\"],[\"情に厚い\",\"じょうにあつい\",\"정이 많다\"]],\"no\":\"'미운 정 고운 정'은 딱 맞는 말이 없어서 풀어서 설명해야 해요.\",\"ex\":[\"毎日世話してたら、情が移っちゃった。\",\"まいにち せわ してたら、 じょうが うつっちゃった。\",\"매일 돌보다 보니 정이 들어 버렸어.\"]},{\"ko\":\"아니에요 (칭찬받았을 때)\",\"c\":\"관계\",\"v\":\"있음\",\"sum\":\"いえいえ나 そんなことないです가 딱 맞아요. 요즘은 ありがとうございます로 받는 것도 자연스러워요.\",\"ja\":[[\"いえいえ\",\"いえいえ\",\"손을 저으며 가볍게\"],[\"そんなことないですよ\",\"そんなことないですよ\",\"'전혀 아니에요' 겸손하게\"],[\"ありがとうございます\",\"ありがとうございます\",\"칭찬을 그대로 고맙게 받을 때\"]],\"no\":\"違います는 '틀렸어요'라는 뜻이라, 칭찬에 쓰면 상대 말을 정정하는 것처럼 들려요.\",\"ex\":[\"いえいえ、まだまだです。\",\"いえいえ、 まだまだです。\",\"아니에요, 아직 멀었어요.\"]},{\"ko\":\"언니 / 오빠 (호칭)\",\"c\":\"관계\",\"v\":\"없음\",\"sum\":\"친한 언니·오빠도 이름에 さん이나 ちゃん을 붙여 불러요. お姉さん·お兄さん은 진짜 형제나 모르는 사람을 부르는 말이에요.\",\"ja\":[[\"ゆいさん\",\"ゆいさん\",\"이름+さん이 기본. 나이와 상관없이 써요\"],[\"ゆいちゃん\",\"ゆいちゃん\",\"친한 여자 친구·동생에게\"],[\"ゆい先輩\",\"ゆいせんぱい\",\"학교·동아리 선배라면\"]],\"no\":\"친한 오빠를 お兄さん이라고 부르면 진짜 친오빠나 '거기 젊은 남자분'처럼 들려요.\",\"ex\":[\"ゆいさん、今日一緒に帰りませんか。\",\"ゆいさん、 きょう いっしょに かえりませんか。\",\"유이 언니, 오늘 같이 갈래요?\"]},{\"ko\":\"선배\",\"c\":\"관계\",\"v\":\"있음\",\"sum\":\"先輩는 그대로 통해요! 다만 회사에선 선배를 성+さん으로 부르는 경우가 더 많아요.\",\"ja\":[[\"先輩\",\"せんぱい\",\"학교·동아리에서 부를 때 그대로\"],[\"田中さん\",\"たなかさん\",\"회사 선배는 보통 성+さん\"]],\"no\":\"회사 상사를 先輩라고 부르면 학생 같은 느낌이 나요. 직함이나 さん을 써요.\",\"ex\":[\"先輩、ちょっと相談してもいいですか。\",\"せんぱい、 ちょっと そうだん しても いいですか。\",\"선배, 잠깐 상담해도 될까요?\"]},{\"ko\":\"덕분에요\",\"c\":\"관계\",\"v\":\"있음\",\"sum\":\"おかげさまで가 딱 맞아요. 상대가 직접 도와준 게 없어도 '덕분에 잘 지내요'처럼 인사로 써요.\",\"ja\":[[\"おかげさまで\",\"おかげさまで\",\"안부 인사에 대한 대답으로도\"],[\"田中さんのおかげです\",\"たなかさんのおかげです\",\"누구 덕분인지 콕 집어 말할 때\"]],\"no\":\"\",\"ex\":[\"おかげさまで、無事に終わりました。\",\"おかげさまで、 ぶじに おわりました。\",\"덕분에 무사히 끝났어요.\"]},{\"ko\":\"우리 (우리 엄마)\",\"c\":\"관계\",\"v\":\"상황따라\",\"sum\":\"'우리 엄마'는 うちの母, '우리 회사'는 うちの会社예요. 私たちの母라고 하면 형제가 함께 말하는 것처럼 들려요.\",\"ja\":[[\"うちの母\",\"うちのはは\",\"남에게 우리 엄마를 말할 때\"],[\"うちの会社\",\"うちのかいしゃ\",\"'우리 회사' (편하게)\"],[\"弊社\",\"へいしゃ\",\"비즈니스에서 우리 회사를 낮춰 말할 때\"]],\"no\":\"'우리나라'를 私たちの国라고 하면 어색해요. 그냥 韓国라고 하는 게 자연스러워요.\",\"ex\":[\"うちの母は料理が上手です。\",\"うちの ははは りょうりが じょうずです。\",\"우리 엄마는 요리를 잘해요.\"]},{\"ko\":\"썸\",\"c\":\"관계\",\"v\":\"상황따라\",\"sum\":\"いい感じ가 가장 가까워요. '요즘 썸 타는 사람 있어'는 最近いい感じの人がいる.\",\"ja\":[[\"いい感じ\",\"いいかんじ\",\"'썸 타는 중'의 그 느낌\"],[\"友達以上恋人未満\",\"ともだちいじょうこいびとみまん\",\"친구 이상 연인 미만\"]],\"no\":\"\",\"ex\":[\"最近、いい感じの人がいるんだ。\",\"さいきん、 いい かんじの ひとが いるんだ。\",\"요즘 썸 타는 사람 있어.\"]},{\"ko\":\"괜찮아요 (거절할 때)\",\"c\":\"가게·여행\",\"v\":\"있음\",\"sum\":\"요즘 일본어도 大丈夫です를 거절에 똑같이 써요. 다만 애매하게 들릴 수 있으니 손을 살짝 저어 주면 확실해요.\",\"ja\":[[\"大丈夫です\",\"だいじょうぶです\",\"'봉투 필요하세요?' 같은 질문에 '괜찮아요(필요 없어요)'\"],[\"結構です\",\"けっこうです\",\"확실한 거절. 조금 딱딱해서 차갑게 들릴 수 있어요\"],[\"遠慮しておきます\",\"えんりょしておきます\",\"권유를 부드럽게 사양할 때\"]],\"no\":\"大丈夫です만 말하면 '네, 괜찮아요(주세요)'로 오해받기도 해요. 손짓을 더하면 안전해요.\",\"ex\":[\"袋は大丈夫です。\",\"ふくろは だいじょうぶです。\",\"봉투는 괜찮아요.\"]},{\"ko\":\"감사합니다 (가게에서 손님이)\",\"c\":\"가게·여행\",\"v\":\"상황따라\",\"sum\":\"일본 손님은 계산할 때 말없이 고개만 살짝 숙이는 경우도 많아요. 식당을 나설 땐 ごちそうさまでした가 딱이에요.\",\"ja\":[[\"ごちそうさまでした\",\"ごちそうさまでした\",\"식당에서 계산하고 나갈 때\"],[\"ありがとうございます\",\"ありがとうございます\",\"물건·거스름돈을 받을 때. 해도 전혀 이상하지 않아요\"],[\"どうも\",\"どうも\",\"가볍게 고개 숙이며 '고마워요'\"]],\"no\":\"\",\"ex\":[\"どうも、ごちそうさまでした。\",\"どうも、 ごちそうさまでした。\",\"감사합니다, 잘 먹었습니다.\"]},{\"ko\":\"사장님 (가게 주인 부를 때)\",\"c\":\"가게·여행\",\"v\":\"상황따라\",\"sum\":\"社長는 진짜 회사 사장에게만 써요. 가게에선 すみません, 단골 가게라면 大将나 マスター.\",\"ja\":[[\"すみません\",\"すみません\",\"누구든 부를 때 기본\"],[\"大将\",\"たいしょう\",\"초밥집·이자카야의 남자 주인에게 단골이 친근하게\"],[\"マスター\",\"マスター\",\"바·카페 주인에게\"]],\"no\":\"社長는 유흥가 호객꾼이 손님을 띄울 때 쓰는 말로도 알려져 있어서, 가게 주인에게 쓰면 어색해요.\",\"ex\":[\"大将、おすすめは何ですか。\",\"たいしょう、 おすすめは なんですか。\",\"사장님, 추천 메뉴 뭐예요?\"]},{\"ko\":\"이모 (식당)\",\"c\":\"가게·여행\",\"v\":\"없음\",\"sum\":\"식당 직원을 가족 호칭으로 부르는 문화가 없어요. すみません 하나면 충분해요.\",\"ja\":[[\"すみません\",\"すみません\",\"직원을 부를 때는 이걸로 충분해요\"]],\"no\":\"おばさん이라고 부르면 '아줌마'처럼 들려 실례가 될 수 있어요.\",\"ex\":[\"すみません、お水ください。\",\"すみません、 おみず ください。\",\"이모, 여기 물 좀 주세요.\"]},{\"ko\":\"저기요 (점원 부를 때)\",\"c\":\"가게·여행\",\"v\":\"있음\",\"sum\":\"すみません이 딱 맞아요. 손을 살짝 들면서 말하면 돼요.\",\"ja\":[[\"すみません\",\"すみません\",\"점원을 부를 때\"],[\"すみません、お願いします\",\"すみません、おねがいします\",\"주문하고 싶을 때\"]],\"no\":\"あのう는 말을 꺼내기 전의 '저…'라서 멀리 있는 점원을 부르기엔 약해요. 테이블에 호출 버튼이 있으면 그걸 눌러요.\",\"ex\":[\"すみません、注文お願いします。\",\"すみません、 ちゅうもん おねがいします。\",\"저기요, 주문할게요.\"]},{\"ko\":\"계산해 주세요\",\"c\":\"가게·여행\",\"v\":\"있음\",\"sum\":\"お会計お願いします가 가장 무난해요. 자리에서 계산하는 가게도 많아요.\",\"ja\":[[\"お会計お願いします\",\"おかいけいおねがいします\",\"가장 무난한 표현\"],[\"お勘定お願いします\",\"おかんじょうおねがいします\",\"조금 예스러운 표현. 이자카야 등에서\"]],\"no\":\"단골 흉내로 お愛想라고 하면, 원래 가게 쪽에서 쓰던 말이라 실례로 여기는 사람도 있어요.\",\"ex\":[\"すみません、お会計お願いします。\",\"すみません、 おかいけい おねがいします。\",\"저기요, 계산해 주세요.\"]},{\"ko\":\"서비스예요\",\"c\":\"가게·여행\",\"v\":\"있음\",\"sum\":\"サービス를 '공짜로 드려요'라는 뜻으로 한국과 똑같이 써요. 덤은 おまけ라고도 해요.\",\"ja\":[[\"サービスです\",\"サービスです\",\"가게가 공짜로 줄 때\"],[\"おまけです\",\"おまけです\",\"덤으로 하나 더 줄 때\"]],\"no\":\"\",\"ex\":[\"これ、サービスです。どうぞ。\",\"これ、 サービスです。 どうぞ。\",\"이거 서비스예요. 드세요.\"]},{\"ko\":\"깎아 주세요\",\"c\":\"가게·여행\",\"v\":\"상황따라\",\"sum\":\"일본은 정찰제가 기본이라 흥정할 일이 드물어요. 가전 매장이나 시장에서는 정중하게 물어볼 수 있어요.\",\"ja\":[[\"もう少し安くなりませんか\",\"もうすこしやすくなりませんか\",\"흥정이 가능한 곳에서 정중하게\"],[\"まけてくれへん？\",\"まけてくれへん？\",\"오사카 사투리로 유명한 '좀 깎아 줘'\"]],\"no\":\"편의점·백화점·일반 가게에서 깎아 달라고 하면 점원이 당황해요.\",\"ex\":[\"これ、もう少し安くなりませんか。\",\"これ、 もう すこし やすく なりませんか。\",\"이거 좀 깎아 주실 수 있어요?\"]}]");
const KANSAI_RAW = JSON.parse("[{\"w\":\"おおきに\",\"r\":\"おおきに\",\"std\":\"ありがとう\",\"m\":\"고마워요\",\"c\":\"인사\",\"n\":\"오사카 가게에서 자주 들어요. 손님이 써도 좋아요.\",\"o\":[\"안녕히 가세요\",\"잘 먹겠습니다\",\"실례합니다\"],\"ex\":\"おおきに、また来てな。\",\"exr\":\"おおきに、 また きて な。\",\"exko\":\"고마워, 또 와.\"},{\"w\":\"まいど\",\"r\":\"まいど\",\"std\":\"毎度ありがとうございます\",\"m\":\"늘 고마워요(가게 인사)\",\"c\":\"인사\",\"n\":\"가게에 들어가면 '어서 와요', 나갈 땐 '고마워요' 느낌으로 들어요. 'まいどおおきに'라고도 해요.\",\"o\":[\"또 만나요\",\"수고하셨습니다\",\"처음 뵙겠습니다\"],\"ex\":\"まいど！今日は何にしましょ？\",\"exr\":\"まいど！ きょう は なに に しましょ？\",\"exko\":\"어서 와요! 오늘은 뭐로 할까요?\"},{\"w\":\"ほなな\",\"r\":\"ほなな\",\"std\":\"じゃあね\",\"m\":\"그럼 안녕(잘 가)\",\"c\":\"인사\",\"n\":\"친구끼리 헤어질 때 가볍게 써요. 'ほな、また'라고도 해요.\",\"o\":[\"잘 먹었어요\",\"어서 와\",\"잘 자\"],\"ex\":\"ほなな、また明日。\",\"exr\":\"ほなな、 また あした。\",\"exko\":\"그럼 안녕, 내일 봐.\"},{\"w\":\"もうかりまっか\",\"r\":\"もうかりまっか\",\"std\":\"もうかっていますか\",\"m\":\"요즘 장사 잘 돼요?\",\"c\":\"인사\",\"n\":\"옛 오사카 상인 인사로 유명해요. 대답은 'ぼちぼちでんな(그럭저럭이죠)'. 요즘은 주로 농담처럼 들어요.\",\"o\":[\"어디 가세요?\",\"식사하셨어요?\",\"이거 얼마예요?\"],\"ex\":\"大将、もうかりまっか？\",\"exr\":\"たいしょう、 もうかりまっか？\",\"exko\":\"사장님, 요즘 장사 잘 돼요?\"},{\"w\":\"おはようさん\",\"r\":\"おはようさん\",\"std\":\"おはよう\",\"m\":\"좋은 아침(아침 인사)\",\"c\":\"인사\",\"n\":\"おはよう에 'さん'을 붙여 더 다정하게 들려요. 동네 어르신에게서 자주 들어요.\",\"o\":[\"잘 자요\",\"다녀오겠습니다\",\"오랜만이에요\"],\"ex\":\"おはようさん、今日も暑いなあ。\",\"exr\":\"おはようさん、 きょう も あつい なあ。\",\"exko\":\"좋은 아침, 오늘도 덥네.\"},{\"w\":\"なんでやねん\",\"r\":\"なんでやねん\",\"std\":\"なんでだよ\",\"m\":\"왜 그렇게 되는데!(태클)\",\"c\":\"맞장구·리액션\",\"n\":\"엉뚱한 말에 웃으며 던지는 츳코미(태클)예요. 진짜 화난 게 아니에요. 개그에서 정말 자주 들어요.\",\"o\":[\"왜 울어?\",\"언제 끝나?\",\"어디서 샀어?\"],\"ex\":\"犬がしゃべった？なんでやねん！\",\"exr\":\"いぬ が しゃべった？ なんで やねん！\",\"exko\":\"개가 말을 했다고? 그게 말이 돼!\"},{\"w\":\"ほんまに？\",\"r\":\"ほんまに\",\"std\":\"本当に？\",\"m\":\"진짜로?\",\"c\":\"맞장구·리액션\",\"n\":\"놀랐을 때 끝을 올려 말하는 맞장구예요. 'ほんま？'만 해도 돼요.\",\"o\":[\"정말 고마워\",\"정말 미안해\",\"거짓말하지 마\"],\"ex\":\"え、ほんまに？すごいやん！\",\"exr\":\"え、 ほんまに？ すごい やん！\",\"exko\":\"어, 진짜로? 대단하다!\"},{\"w\":\"ちゃうちゃう\",\"r\":\"ちゃうちゃう\",\"std\":\"違う違う\",\"m\":\"아니야 아니야\",\"c\":\"맞장구·리액션\",\"n\":\"손을 저으며 강하게 아니라고 할 때 써요. 'ちゃうちゃうちゃう?'(차우차우 아니야?) 같은 말장난도 유명해요.\",\"o\":[\"맞아 맞아\",\"좋아 좋아\",\"천천히 천천히\"],\"ex\":\"ちゃうちゃう、そうやないねん。\",\"exr\":\"ちゃうちゃう、 そう や ない ねん。\",\"exko\":\"아니 아니, 그게 아니라니까.\"},{\"w\":\"せやな\",\"r\":\"せやな\",\"std\":\"そうだね\",\"m\":\"그렇지, 맞아\",\"c\":\"맞장구·리액션\",\"n\":\"가장 흔한 맞장구예요. 'そやな'도 같은 뜻. 'せや!'는 '아, 맞다!'처럼 뭔가 생각났을 때도 써요.\",\"o\":[\"글쎄\",\"그만해\",\"잘 모르겠어\"],\"ex\":\"せやな、ほな行こか。\",\"exr\":\"せやな、 ほな いこ か。\",\"exko\":\"그러네, 그럼 갈까?\"},{\"w\":\"ええやん\",\"r\":\"ええやん\",\"std\":\"いいじゃん\",\"m\":\"좋은데!, 괜찮네!\",\"c\":\"맞장구·리액션\",\"n\":\"칭찬하거나 찬성할 때 써요. 친구 옷이나 사진에 한마디 하기 좋아요.\",\"o\":[\"별로야\",\"그만해\",\"아직이야\"],\"ex\":\"その服、ええやん！\",\"exr\":\"その ふく、 ええ やん！\",\"exko\":\"그 옷 좋은데!\"},{\"w\":\"いけるいける\",\"r\":\"いけるいける\",\"std\":\"大丈夫大丈夫\",\"m\":\"괜찮아 괜찮아, 할 수 있어\",\"c\":\"맞장구·리액션\",\"n\":\"걱정하는 사람을 격려할 때 써요. 'いける?'는 '괜찮아? 할 수 있어?'라고 묻는 말이에요.\",\"o\":[\"가자 가자\",\"먹어 먹어\",\"빨리 빨리\"],\"ex\":\"いけるいける、まだ間に合うで。\",\"exr\":\"いける いける、 まだ まにあう で。\",\"exko\":\"괜찮아 괜찮아, 아직 안 늦었어.\"},{\"w\":\"知らんけど\",\"r\":\"しらんけど\",\"std\":\"知らないけど\",\"m\":\"잘은 모르지만(아님 말고)\",\"c\":\"맞장구·리액션\",\"n\":\"말끝에 붙여 '확실하진 않아'라는 느낌을 줘요. 오사카 사람의 유머 섞인 말버릇으로 유명해요.\",\"o\":[\"알려 줘서 고마워\",\"다 알고 있어\",\"물어봐도 돼?\"],\"ex\":\"あの店、たぶん安いで。知らんけど。\",\"exr\":\"あの みせ、 たぶん やすい で。 しらん けど。\",\"exko\":\"그 가게 아마 쌀걸. 잘은 모르지만.\"},{\"w\":\"よう言わんわ\",\"r\":\"よういわんわ\",\"std\":\"あきれて何も言えない\",\"m\":\"어이가 없네, 할 말이 없다\",\"c\":\"맞장구·리액션\",\"n\":\"기가 막힐 때 웃으면서 하는 말이에요. 상대를 진지하게 비난하는 말은 아니에요.\",\"o\":[\"말 잘하네\",\"잘 들려\",\"다시 말해 줘\"],\"ex\":\"また財布忘れたん？よう言わんわ。\",\"exr\":\"また さいふ わすれたん？ よう いわん わ。\",\"exko\":\"또 지갑 두고 왔어? 어이가 없네.\"},{\"w\":\"しゃあない\",\"r\":\"しゃあない\",\"std\":\"仕方ない\",\"m\":\"어쩔 수 없지\",\"c\":\"맞장구·리액션\",\"n\":\"'しょうがない'의 간사이 버전이에요. 포기하고 받아들일 때 많이 들어요.\",\"o\":[\"큰일 났다\",\"다행이다\",\"말도 안 돼\"],\"ex\":\"雨やし、しゃあないな。\",\"exr\":\"あめ や し、 しゃあない な。\",\"exko\":\"비 오니까 어쩔 수 없지.\"},{\"w\":\"そんなアホな\",\"r\":\"そんなあほな\",\"std\":\"そんなばかな\",\"m\":\"말도 안 돼!, 설마!\",\"c\":\"맞장구·리액션\",\"n\":\"믿기 힘든 일에 대한 리액션이에요. 단 'アホ'(바보)를 사람에게 쓰는 건 친한 사이 농담일 때만! 모르는 사람에게는 쓰지 마세요.\",\"o\":[\"그 사람 바보야\",\"너무 웃겨\",\"정말 잘됐다\"],\"ex\":\"え、もう売り切れ？そんなアホな！\",\"exr\":\"え、 もう うりきれ？ そんな あほな！\",\"exko\":\"어, 벌써 품절이라고? 말도 안 돼!\"},{\"w\":\"ぼちぼち\",\"r\":\"ぼちぼち\",\"std\":\"まあまあ\",\"m\":\"그럭저럭\",\"c\":\"맞장구·리액션\",\"n\":\"'요즘 어때?'에 대한 단골 대답이에요. 'ぼちぼち行こか'는 '슬슬 갈까'라는 뜻이 돼요.\",\"o\":[\"아주 좋아\",\"최악이야\",\"처음이야\"],\"ex\":\"仕事？まあ、ぼちぼちやな。\",\"exr\":\"しごと？ まあ、 ぼちぼち や な。\",\"exko\":\"일? 뭐, 그럭저럭이야.\"},{\"w\":\"しんどい\",\"r\":\"しんどい\",\"std\":\"疲れた・つらい\",\"m\":\"힘들어, 지쳐\",\"c\":\"감정\",\"n\":\"몸이 피곤할 때도, 마음이 힘들 때도 써요. 요즘은 전국에서 통하는 말이에요.\",\"o\":[\"배고파\",\"심심해\",\"신나\"],\"ex\":\"今日はめっちゃ歩いたから、しんどいわ。\",\"exr\":\"きょう は めっちゃ あるいた から、 しんどい わ。\",\"exko\":\"오늘 엄청 걸어서 힘들어.\"},{\"w\":\"おもろい\",\"r\":\"おもろい\",\"std\":\"面白い\",\"m\":\"재밌어, 웃겨\",\"c\":\"감정\",\"n\":\"오사카에서는 최고의 칭찬 중 하나예요. 반대말 'おもんない'는 '재미없어'.\",\"o\":[\"무서워\",\"이상해\",\"귀여워\"],\"ex\":\"あの芸人、めっちゃおもろいな。\",\"exr\":\"あの げいにん、 めっちゃ おもろい な。\",\"exko\":\"저 개그맨 완전 웃기다.\"},{\"w\":\"堪忍な\",\"r\":\"かんにんな\",\"std\":\"ごめんね\",\"m\":\"미안해(봐줘)\",\"c\":\"감정\",\"n\":\"부드럽게 사과하는 말이에요. 조금 예스럽고 다정한 느낌이라 어르신에게서 자주 들어요. '堪忍して'는 '봐줘'.\",\"o\":[\"괜찮아\",\"참아\",\"고마워\"],\"ex\":\"遅れてしもて、堪忍な。\",\"exr\":\"おくれて しもて、 かんにん な。\",\"exko\":\"늦어서 미안해.\"},{\"w\":\"しもた\",\"r\":\"しもた\",\"std\":\"しまった\",\"m\":\"아차, 큰일 났다\",\"c\":\"감정\",\"n\":\"실수를 깨달았을 때 하는 혼잣말이에요. '〜てもうた'(~해 버렸다)도 함께 알아 두세요.\",\"o\":[\"다 했다\",\"잘됐다\",\"닫혔다\"],\"ex\":\"しもた！傘忘れてもうた。\",\"exr\":\"しもた！ かさ わすれて もうた。\",\"exko\":\"아차! 우산 놓고 왔다.\"},{\"w\":\"けったいな\",\"r\":\"けったいな\",\"std\":\"変な\",\"m\":\"이상한, 별난\",\"c\":\"감정\",\"n\":\"'희한하네' 정도의 가벼운 느낌이에요. 사람에게 쓰면 실례일 수 있으니 날씨나 물건, 상황에 쓰세요.\",\"o\":[\"멋진\",\"비싼\",\"오래된\"],\"ex\":\"今日はけったいな天気やなあ。\",\"exr\":\"きょう は けったいな てんき や なあ。\",\"exko\":\"오늘 날씨 희한하네.\"},{\"w\":\"ほな\",\"r\":\"ほな\",\"std\":\"じゃあ・それでは\",\"m\":\"그럼\",\"c\":\"일상\",\"n\":\"대화를 마무리하거나 다음으로 넘어갈 때 써요. 'ほんなら'가 줄어든 말이에요.\",\"o\":[\"그래도\",\"왜냐하면\",\"아까\"],\"ex\":\"ほな、そろそろ帰ろか。\",\"exr\":\"ほな、 そろそろ かえろ か。\",\"exko\":\"그럼 슬슬 돌아갈까?\"},{\"w\":\"めっちゃ\",\"r\":\"めっちゃ\",\"std\":\"とても\",\"m\":\"엄청, 완전\",\"c\":\"일상\",\"n\":\"간사이에서 퍼져 지금은 전국 젊은이들이 써요. 'めっちゃええやん'처럼 어디에나 붙여요.\",\"o\":[\"조금\",\"가끔\",\"절대\"],\"ex\":\"このたこ焼き、めっちゃおいしいやん。\",\"exr\":\"この たこやき、 めっちゃ おいしい やん。\",\"exko\":\"이 타코야키 완전 맛있잖아.\"},{\"w\":\"ほんま\",\"r\":\"ほんま\",\"std\":\"本当\",\"m\":\"진짜, 정말\",\"c\":\"일상\",\"n\":\"'本当(ほんとう)'의 간사이 버전이에요. 'ほんまに'(정말로)도 아주 자주 들어요.\",\"o\":[\"가짜\",\"아마\",\"보통\"],\"ex\":\"それ、ほんまの話？\",\"exr\":\"それ、 ほんま の はなし？\",\"exko\":\"그거 진짜 이야기야?\"},{\"w\":\"あかん\",\"r\":\"あかん\",\"std\":\"だめ\",\"m\":\"안 돼\",\"c\":\"일상\",\"n\":\"금지, 실패, 곤란 모두에 써요. 'あかんわ'는 '안 되겠다, 틀렸다'.\",\"o\":[\"열려 있어\",\"괜찮아\",\"몰라\"],\"ex\":\"そこ入ったらあかんで。\",\"exr\":\"そこ はいったら あかん で。\",\"exko\":\"거기 들어가면 안 돼.\"},{\"w\":\"ちゃう\",\"r\":\"ちゃう\",\"std\":\"違う\",\"m\":\"아니야, 달라\",\"c\":\"일상\",\"n\":\"'違う(ちがう)'가 줄어든 말이에요. 길을 물으면 'そっちちゃうで'(그쪽 아니야) 같은 말을 들을 수 있어요.\",\"o\":[\"맞아\",\"작아\",\"가자\"],\"ex\":\"それ、ちゃうで。こっちやで。\",\"exr\":\"それ、 ちゃう で。 こっち や で。\",\"exko\":\"그거 아니야. 이쪽이야.\"},{\"w\":\"ええ\",\"r\":\"ええ\",\"std\":\"いい\",\"m\":\"좋아\",\"c\":\"일상\",\"n\":\"'いい'의 간사이 버전이에요. 'ええよ'는 '좋아, 괜찮아'. 'もうええわ'는 상황에 따라 '이제 됐어'라는 사양이 돼요.\",\"o\":[\"싫어\",\"나빠\",\"어?\"],\"ex\":\"今日はええ天気やなあ。\",\"exr\":\"きょう は ええ てんき や なあ。\",\"exko\":\"오늘 날씨 좋네.\"},{\"w\":\"かまへん\",\"r\":\"かまへん\",\"std\":\"かまわない\",\"m\":\"괜찮아, 상관없어\",\"c\":\"일상\",\"n\":\"사과나 부탁을 받았을 때 '괜찮아요'라는 뜻이에요. 여행자가 써도 자연스러워요.\",\"o\":[\"못 참아\",\"기다려\",\"모르겠어\"],\"ex\":\"気にせんでええよ、かまへんかまへん。\",\"exr\":\"き に せんで ええ よ、 かまへん かまへん。\",\"exko\":\"신경 쓰지 마, 괜찮아 괜찮아.\"},{\"w\":\"ほかす\",\"r\":\"ほかす\",\"std\":\"捨てる\",\"m\":\"버리다\",\"c\":\"일상\",\"n\":\"쓰레기를 버릴 때 써요. 다른 지역 사람은 못 알아듣기도 하는 대표 간사이벤이에요.\",\"o\":[\"숨기다\",\"맡기다\",\"데우다\"],\"ex\":\"このゴミ、ほかしといて。\",\"exr\":\"この ごみ、 ほかしといて。\",\"exko\":\"이 쓰레기 좀 버려 줘.\"},{\"w\":\"なおす\",\"r\":\"なおす\",\"std\":\"片付ける\",\"m\":\"(제자리에) 정리하다\",\"c\":\"일상\",\"n\":\"표준어로는 '고치다'지만 간사이에서는 '치우다, 제자리에 두다'로도 써요. 헷갈리기 쉬워요!\",\"o\":[\"꺼내다\",\"다시 하다\",\"씻다\"],\"ex\":\"使ったら、ちゃんとなおしてな。\",\"exr\":\"つかったら、 ちゃんと なおして な。\",\"exko\":\"쓰고 나면 제자리에 잘 갖다 둬.\"},{\"w\":\"ぎょうさん\",\"r\":\"ぎょうさん\",\"std\":\"たくさん\",\"m\":\"많이\",\"c\":\"일상\",\"n\":\"조금 예스러운 말로 어르신에게서 자주 들어요.\",\"o\":[\"조금\",\"천천히\",\"전부\"],\"ex\":\"お土産、ぎょうさん買うたなあ。\",\"exr\":\"おみやげ、 ぎょうさん こうた なあ。\",\"exko\":\"기념품 많이 샀네.\"},{\"w\":\"めばちこ\",\"r\":\"めばちこ\",\"std\":\"ものもらい\",\"m\":\"다래끼\",\"c\":\"일상\",\"n\":\"눈에 나는 다래끼예요. 지역마다 부르는 이름이 달라서 재밌는 단어예요.\",\"o\":[\"눈곱\",\"쌍꺼풀\",\"눈썹\"],\"ex\":\"目にめばちこできてもうた。\",\"exr\":\"め に めばちこ できて もうた。\",\"exko\":\"눈에 다래끼 났어.\"},{\"w\":\"自分\",\"r\":\"じぶん\",\"std\":\"あなた\",\"m\":\"너, 당신\",\"c\":\"일상\",\"n\":\"간사이에서는 상대방을 '自分'이라고 부르기도 해요. 표준어의 '나 자신'과 헷갈리지 마세요!\",\"o\":[\"선생님\",\"우리\",\"그 사람\"],\"ex\":\"自分、どこから来たん？\",\"exr\":\"じぶん、 どこ から きたん？\",\"exko\":\"너 어디서 왔어?\"},{\"w\":\"なんでなん\",\"r\":\"なんでなん\",\"std\":\"どうして？\",\"m\":\"왜? 어째서?\",\"c\":\"일상\",\"n\":\"진짜 이유가 궁금할 때 묻는 말이에요. 태클인 'なんでやねん'과는 달라요.\",\"o\":[\"뭐 먹을래?\",\"언제야?\",\"어디야?\"],\"ex\":\"なんでなん？教えてや。\",\"exr\":\"なんで なん？ おしえて や。\",\"exko\":\"왜? 알려 줘.\"},{\"w\":\"おる\",\"r\":\"おる\",\"std\":\"いる\",\"m\":\"(사람·동물이) 있다\",\"c\":\"일상\",\"n\":\"'いる' 대신 써요. 부정은 'おらん'(없다). 표준어에선 'おります'(겸양)로 주로 쓰지만 오사카에선 평범한 일상어예요.\",\"o\":[\"접다\",\"가다\",\"앉다\"],\"ex\":\"店の前に猫がおるで。\",\"exr\":\"みせ の まえ に ねこ が おる で。\",\"exko\":\"가게 앞에 고양이 있어.\"},{\"w\":\"いてる\",\"r\":\"いてる\",\"std\":\"いる\",\"m\":\"(사람이) 있다\",\"c\":\"일상\",\"n\":\"오사카 쪽에서 쓰는 'いる'예요. 'おる'보다 부드러운 느낌이에요.\",\"o\":[\"아파\",\"울고 있어\",\"입고 있어\"],\"ex\":\"友だち、もう駅にいてるって。\",\"exr\":\"ともだち、 もう えき に いてる って。\",\"exko\":\"친구 벌써 역에 와 있대.\"},{\"w\":\"あめちゃん\",\"r\":\"あめちゃん\",\"std\":\"飴\",\"m\":\"사탕\",\"c\":\"일상\",\"n\":\"오사카 아주머니들이 가방에 넣고 다니며 나눠 주는 걸로 유명해요. 받으면 'おおきに!'\",\"o\":[\"비\",\"귀여운 아기\",\"떡\"],\"ex\":\"あめちゃん食べる？\",\"exr\":\"あめちゃん たべる？\",\"exko\":\"사탕 먹을래?\"},{\"w\":\"おいもさん\",\"r\":\"おいもさん\",\"std\":\"さつまいも\",\"m\":\"고구마(친근한 말)\",\"c\":\"일상\",\"n\":\"간사이(특히 교토)에서는 음식에 'さん'을 붙여 부르기도 해요. おまめさん(콩), おかゆさん(죽)처럼요.\",\"o\":[\"감자 아저씨\",\"옥수수\",\"밤\"],\"ex\":\"焼いたおいもさん、甘いなあ。\",\"exr\":\"やいた おいもさん、 あまい なあ。\",\"exko\":\"군고구마 달다.\"},{\"w\":\"えらい\",\"r\":\"えらい\",\"std\":\"とても・ひどく\",\"m\":\"엄청, 굉장히\",\"c\":\"일상\",\"n\":\"표준어의 '훌륭하다'와 달리 간사이에선 '엄청'이라는 강조로 많이 써요. 'えらいこっちゃ'는 '큰일 났다'.\",\"o\":[\"느리다\",\"귀찮다\",\"조용하다\"],\"ex\":\"えらい混んでるなあ。\",\"exr\":\"えらい こんでる なあ。\",\"exko\":\"엄청 붐비네.\"},{\"w\":\"行こか\",\"r\":\"いこか\",\"std\":\"行こうか\",\"m\":\"갈까?, 가자\",\"c\":\"일상\",\"n\":\"출발할 때 단골 표현이에요. '食べよか'(먹을까?)처럼 다른 동사에도 써요.\",\"o\":[\"가지 마\",\"갔다 왔어\",\"가고 싶어\"],\"ex\":\"もうすぐ電車来るし、行こか。\",\"exr\":\"もうすぐ でんしゃ くる し、 いこ か。\",\"exko\":\"곧 전철 오니까 가자.\"},{\"w\":\"なんぼ\",\"r\":\"なんぼ\",\"std\":\"いくら\",\"m\":\"얼마\",\"c\":\"가게·여행\",\"n\":\"가격을 물을 때 써요. 'これ、なんぼ?'만 말해도 통해요.\",\"o\":[\"몇 시\",\"몇 개\",\"어디\"],\"ex\":\"これ、なんぼ？\",\"exr\":\"これ、 なんぼ？\",\"exko\":\"이거 얼마예요?\"},{\"w\":\"まけて\",\"r\":\"まけて\",\"std\":\"安くして\",\"m\":\"깎아 주세요\",\"c\":\"가게·여행\",\"n\":\"'まける'(값을 깎다)는 표준어에도 있지만 흥정 문화로 유명한 오사카에서 특히 많이 들어요. 체인점이나 백화점에선 깎지 않아요.\",\"o\":[\"영수증 주세요\",\"포장해 주세요\",\"하나 더 주세요\"],\"ex\":\"おっちゃん、ちょっとまけてや。\",\"exr\":\"おっちゃん、 ちょっと まけて や。\",\"exko\":\"아저씨, 좀 깎아 줘요.\"},{\"w\":\"いらん\",\"r\":\"いらん\",\"std\":\"いらない\",\"m\":\"필요 없어요\",\"c\":\"가게·여행\",\"n\":\"계산할 때 '袋いらんです'(봉투 필요 없어요)처럼 써 볼 수 있어요. 'いりません'이 더 정중해요.\",\"o\":[\"더 주세요\",\"들어가요\",\"몰라요\"],\"ex\":\"袋はいらんです。\",\"exr\":\"ふくろ は いらん です。\",\"exko\":\"봉투는 필요 없어요.\"},{\"w\":\"待っとってな\",\"r\":\"まっとってな\",\"std\":\"待っていてね\",\"m\":\"잠깐 기다려 줘요\",\"c\":\"가게·여행\",\"n\":\"가게 직원이 '잠깐만 기다려요'라고 할 때 자주 들어요. '〜とって'는 '〜ていて'예요.\",\"o\":[\"가져가세요\",\"먼저 드세요\",\"줄 서지 마세요\"],\"ex\":\"ちょっと待っとってな、すぐ作るで。\",\"exr\":\"ちょっと まっとって な、 すぐ つくる で。\",\"exko\":\"잠깐 기다려요, 바로 만들어 줄게요.\"},{\"w\":\"冷コー\",\"r\":\"れいこー\",\"std\":\"アイスコーヒー\",\"m\":\"아이스커피\",\"c\":\"가게·여행\",\"n\":\"옛 오사카 킷사텐(찻집) 말투예요. 요즘은 어르신이나 레트로 가게에서 가끔 들어요.\",\"o\":[\"냉면\",\"차가운 물\",\"콜라\"],\"ex\":\"冷コーひとつちょうだい。\",\"exr\":\"れいこー ひとつ ちょうだい。\",\"exko\":\"아이스커피 하나 주세요.\"},{\"w\":\"行かへん\",\"r\":\"いかへん\",\"std\":\"行かない\",\"m\":\"안 가\",\"c\":\"문법(어미)\",\"n\":\"'〜ない' 대신 '〜へん'을 써요. 'わからへん'(몰라), 'できへん'(못 해)처럼 정말 자주 들려요.\",\"o\":[\"갈래\",\"갈 수 있어\",\"가야 해\"],\"ex\":\"今日は雨やし、行かへんわ。\",\"exr\":\"きょう は あめ や し、 いかへん わ。\",\"exko\":\"오늘은 비 오니까 안 갈래.\"},{\"w\":\"学生や\",\"r\":\"がくせいや\",\"std\":\"学生だ\",\"m\":\"학생이야\",\"c\":\"문법(어미)\",\"n\":\"'だ' 대신 'や'를 써요. 'そうや'(그래), 'ほんまや'(진짜네)처럼 문장 끝에서 많이 들려요.\",\"o\":[\"학생이니?\",\"학생이었어\",\"학생들\"],\"ex\":\"うちの弟、まだ学生やねん。\",\"exr\":\"うち の おとうと、 まだ がくせい や ねん。\",\"exko\":\"우리 남동생은 아직 학생이야.\"},{\"w\":\"言うてはる\",\"r\":\"いうてはる\",\"std\":\"言っている（おっしゃっている）\",\"m\":\"(그분이) 말씀하고 계셔\",\"c\":\"문법(어미)\",\"n\":\"'〜はる'는 가벼운 높임말이에요. 손님이나 다른 사람을 부드럽게 높일 때 써요. '来はる'(오시다)처럼요.\",\"o\":[\"말해 버렸어\",\"말하지 마\",\"말할 거야\"],\"ex\":\"店長さん、明日休みやって言うてはったで。\",\"exr\":\"てんちょうさん、 あした やすみ や って いうてはった で。\",\"exko\":\"점장님이 내일 쉰다고 하셨어.\"},{\"w\":\"行くで\",\"r\":\"いくで\",\"std\":\"行くよ\",\"m\":\"간다, 가자\",\"c\":\"문법(어미)\",\"n\":\"문장 끝 'で'는 표준어 'よ'와 비슷해요. 'ええで'(좋아), '安いで'(싸요)처럼 가게에서도 자주 들어요.\",\"o\":[\"가서\",\"가니까\",\"갈래?\"],\"ex\":\"ほな、先に行くで！\",\"exr\":\"ほな、 さき に いく で！\",\"exko\":\"그럼 먼저 간다!\"},{\"w\":\"好きやねん\",\"r\":\"すきやねん\",\"std\":\"好きなんだ\",\"m\":\"좋아하거든\",\"c\":\"문법(어미)\",\"n\":\"'〜ねん'은 '〜んだ/〜のだ'예요. 이유를 설명하거나 강조할 때 써요. 고백 표현으로도 유명해요.\",\"o\":[\"좋아했었어\",\"좋아하니?\",\"좋아하지 마\"],\"ex\":\"たこ焼きがほんまに好きやねん。\",\"exr\":\"たこやき が ほんまに すき や ねん。\",\"exko\":\"타코야키를 정말 좋아하거든.\"},{\"w\":\"言うたやんか\",\"r\":\"いうたやんか\",\"std\":\"言ったじゃない\",\"m\":\"말했잖아\",\"c\":\"문법(어미)\",\"n\":\"'〜やんか/〜やん'은 '〜じゃない(~잖아)'예요. 'ええやん'도 같은 끝맺음이에요.\",\"o\":[\"말 안 했어\",\"말해 줄게\",\"말할까?\"],\"ex\":\"せやから言うたやんか。\",\"exr\":\"せやから いうた やんか。\",\"exko\":\"그러니까 말했잖아.\"},{\"w\":\"してんねん\",\"r\":\"してんねん\",\"std\":\"しているんだ\",\"m\":\"~하고 있거든\",\"c\":\"문법(어미)\",\"n\":\"'してる+ねん'이에요. 지금 하는 일을 설명할 때 써요. '何してんねん'은 '뭐 하는 거야!'라는 태클로도 들려요.\",\"o\":[\"해 버렸어\",\"할 거야\",\"하지 마\"],\"ex\":\"今、大阪で日本語勉強してんねん。\",\"exr\":\"いま、 おおさか で にほんご べんきょう してん ねん。\",\"exko\":\"지금 오사카에서 일본어 공부하고 있거든.\"},{\"w\":\"高いんちゃう？\",\"r\":\"たかいんちゃう\",\"std\":\"高いんじゃない？\",\"m\":\"비싸지 않아?\",\"c\":\"문법(어미)\",\"n\":\"문장 끝 '〜ちゃう?'는 '〜じゃない?(~지 않아?)'라는 추측이나 제안이에요. 'ええんちゃう?'(괜찮지 않아?)도 많이 들어요.\",\"o\":[\"안 비싸\",\"너무 비싸요\",\"비싼 거 주세요\"],\"ex\":\"それ、ちょっと高いんちゃう？\",\"exr\":\"それ、 ちょっと たかい ん ちゃう？\",\"exko\":\"그거 좀 비싸지 않아?\"},{\"w\":\"撮ったろか\",\"r\":\"とったろか\",\"std\":\"撮ってあげようか\",\"m\":\"찍어 줄까?\",\"c\":\"문법(어미)\",\"n\":\"'〜たろか'는 '~해 줄까?'예요. 관광지에서 친절한 오사카 사람이 사진을 찍어 주겠다고 할 때 들을 수 있어요. 'おおきに!'로 답해 보세요.\",\"o\":[\"찍어도 돼?\",\"찍지 마\",\"찍었어?\"],\"ex\":\"写真、撮ったろか？\",\"exr\":\"しゃしん、 とったろ か？\",\"exko\":\"사진 찍어 줄까?\"},{\"w\":\"うまいやろ\",\"r\":\"うまいやろ\",\"std\":\"うまいだろう・おいしいでしょ\",\"m\":\"맛있지?\",\"c\":\"문법(어미)\",\"n\":\"'〜やろ'는 '〜だろう/〜でしょ'예요. 가게 주인이 자신 있게 물을 때 자주 들어요.\",\"o\":[\"맛없지?\",\"맛있었어\",\"맛있게 드세요\"],\"ex\":\"このお好み焼き、うまいやろ？\",\"exr\":\"この おこのみやき、 うまい やろ？\",\"exko\":\"이 오코노미야키 맛있지?\"}]");
